INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106001, 0.0, "キャル", 0.0, 0, 7001, "2030/12/17 14:59:59", 0, 7, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 7002, "2030/12/17 14:59:59", 0, 7, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105801, 0.0, "ペコリーヌ", 0.0, 0, 7003, "2030/12/17 14:59:59", 0, 7, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105801, 0.0, "ペコリーヌ", 0.0, 0, 10001, "2030/12/17 14:59:59", 0, 10, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106001, 0.0, "キャル", 0.0, 0, 10002, "2030/12/17 14:59:59", 0, 10, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 10003, "2030/12/17 14:59:59", 0, 10, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106401, 0.0, "シェフィ", 0.0, 0, 10004, "2030/12/17 14:59:59", 2104010, 10, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 2, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -416.5, 105801, 0.0, "ペコリーヌ", 0.0, 0, 12001, "2030/12/17 14:59:59", 0, 12, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106001, 0.0, "キャル", 0.0, 0, 13001, "2030/12/17 14:59:59", 0, 13, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 13002, "2030/12/17 14:59:59", 0, 13, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106401, 0.0, "シェフィ", 0.0, 0, 13003, "2030/12/17 14:59:59", 2104010, 13, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 2, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105801, 0.0, "ペコリーヌ", 0.0, 0, 13004, "2030/12/17 14:59:59", 0, 13, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 14001, "2030/12/17 14:59:59", 0, 14, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106401, 0.0, "シェフィ", 0.0, 0, 14002, "2030/12/17 14:59:59", 2104010, 14, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 2, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105801, 0.0, "ペコリーヌ", 0.0, 0, 14003, "2030/12/17 14:59:59", 0, 14, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106001, 0.0, "キャル", 0.0, 0, 14004, "2030/12/17 14:59:59", 0, 14, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -470.0, 105901, 0.0, "コッコロ", 0.0, 0, 15001, "2030/12/17 14:59:59", 0, 15, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106401, 0.0, "シェフィ", 0.0, 0, 16001, "2030/12/17 14:59:59", 2104010, 16, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 2, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105801, 0.0, "ペコリーヌ", 0.0, 0, 16002, "2030/12/17 14:59:59", 0, 16, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106001, 0.0, "キャル", 0.0, 0, 16003, "2030/12/17 14:59:59", 0, 16, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 16004, "2030/12/17 14:59:59", 0, 16, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 17002, "2030/12/17 14:59:59", 0, 17, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106001, 0.0, "キャル", 0.0, 0, 17004, "2030/12/17 14:59:59", 0, 25, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 17005, "2030/12/17 14:59:59", 0, 25, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106401, 0.0, "シェフィ", 0.0, 0, 17006, "2030/12/17 14:59:59", 2104010, 25, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 2, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105801, 0.0, "ペコリーヌ", 0.0, 0, 17007, "2030/12/17 14:59:59", 0, 25, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 190801, 0.0, "カリン", 0.0, 0, 18001, "2030/12/17 14:59:59", 0, 18, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (2, "2015/12/17 15:00:00", -363.0, 190801, 0.0, "カリン", 0.0, 0, 18002, "2030/12/17 14:59:59", 0, 18, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (3, "2015/12/17 15:00:00", -470.0, 190801, 0.0, "カリン", 0.0, 0, 19001, "2030/12/17 14:59:59", 0, 19, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (4, "2015/12/17 15:00:00", -470.0, 190801, 0.0, "カリン", 0.0, 0, 19002, "2030/12/17 14:59:59", 0, 19, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (5, "2015/12/17 15:00:00", -470.0, 190801, 0.0, "カリン", 0.0, 0, 20001, "2030/12/17 14:59:59", 0, 20, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (6, "2015/12/17 15:00:00", -470.0, 190801, 0.0, "カリン", 0.0, 0, 20002, "2030/12/17 14:59:59", 0, 20, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106001, 0.0, "キャル", 0.0, 0, 21001, "2030/12/17 14:59:59", 0, 21, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 21002, "2030/12/17 14:59:59", 0, 21, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106401, 0.0, "シェフィ", 0.0, 0, 21003, "2030/12/17 14:59:59", 2104010, 21, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 2, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105801, 0.0, "ペコリーヌ", 0.0, 0, 21004, "2030/12/17 14:59:59", 0, 21, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -430.0, 190801, 0.0, "カリン", 0.0, 0, 22001, "2030/12/17 14:59:59", 0, 22, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (2, "2015/12/17 15:00:00", -430.0, 190801, 0.0, "カリン", 0.0, 0, 22002, "2030/12/17 14:59:59", 0, 22, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (3, "2015/12/17 15:00:00", -430.0, 190801, 0.0, "カリン", 0.0, 0, 23001, "2030/12/17 14:59:59", 0, 23, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (4, "2015/12/17 15:00:00", -430.0, 190801, 0.0, "カリン", 0.0, 0, 23002, "2030/12/17 14:59:59", 0, 23, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2019/01/31 12:00:00", -385.0, 109001, 8.0, "エリコ（バレンタイン）", 4.08, 10011, 24001, "2030/12/17 14:59:59", 0, 24, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 1, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (2, "2019/01/31 12:00:00", -385.0, 109001, 8.0, "エリコ（バレンタイン）", 5.0, 10011, 24002, "2030/12/17 14:59:59", 0, 24, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 1, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (3, "2019/01/31 12:00:00", -385.0, 109001, 8.0, "エリコ（バレンタイン）", 10.11, 10011, 24003, "2030/12/17 14:59:59", 0, 24, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 1, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (4, "2019/01/31 12:00:00", -385.0, 109001, 8.0, "エリコ（バレンタイン）", 4.0, 10011, 24004, "2030/12/17 14:59:59", 0, 24, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 1, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (5, "2019/01/31 12:00:00", -385.0, 109001, 8.0, "エリコ（バレンタイン）", 6.0, 10011, 24005, "2030/12/17 14:59:59", 0, 24, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 1, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (6, "2019/01/31 12:00:00", 0.0, 109002, 0.0, "エリコ（バレンタイン）", 0.0, 10011, 24006, "2030/12/17 14:59:59", 0, 24, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (7, "2019/01/31 12:00:00", 0.0, 109002, 0.0, "エリコ（バレンタイン）", 0.0, 10011, 24007, "2030/12/17 14:59:59", 0, 24, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (8, "2019/01/31 12:00:00", 0.0, 109002, 0.0, "エリコ（バレンタイン）", 0.0, 10011, 24008, "2030/12/17 14:59:59", 0, 24, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (9, "2019/01/31 12:00:00", 0.0, 109002, 0.0, "エリコ（バレンタイン）", 0.0, 10011, 24009, "2030/12/17 14:59:59", 0, 24, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (10, "2019/01/31 12:00:00", 0.0, 109002, 0.0, "エリコ（バレンタイン）", 0.0, 10011, 24010, "2030/12/17 14:59:59", 0, 24, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2019/01/31 12:00:00", -385.0, 109101, 8.0, "シズル（バレンタイン）", 2.12, 10011, 24011, "2030/12/17 14:59:59", 0, 24, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 1, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (2, "2019/01/31 12:00:00", -385.0, 109101, 8.0, "シズル（バレンタイン）", 4.19, 10011, 24012, "2030/12/17 14:59:59", 0, 24, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 5, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (3, "2019/01/31 12:00:00", -385.0, 109101, 8.0, "シズル（バレンタイン）", 2.3, 10011, 24013, "2030/12/17 14:59:59", 0, 24, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 2, 4);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (4, "2019/01/31 12:00:00", 0.0, 109102, 0.0, "シズル（バレンタイン）", 0.0, 10011, 24014, "2030/12/17 14:59:59", 0, 24, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (5, "2019/01/31 12:00:00", -385.0, 109101, 8.0, "シズル（バレンタイン）", 5.23, 10011, 24015, "2030/12/17 14:59:59", 0, 24, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 5, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (6, "2019/01/31 12:00:00", 0.0, 109102, 0.0, "シズル（バレンタイン）", 0.0, 10011, 24016, "2030/12/17 14:59:59", 0, 24, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (7, "2019/01/31 12:00:00", -385.0, 109101, 8.0, "シズル（バレンタイン）", 5.01, 10011, 24017, "2030/12/17 14:59:59", 0, 24, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 1, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (8, "2019/01/31 12:00:00", 0.0, 109102, 0.0, "シズル（バレンタイン）", 0.0, 10011, 24018, "2030/12/17 14:59:59", 0, 24, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (9, "2019/01/31 12:00:00", 0.0, 109102, 0.0, "シズル（バレンタイン）", 0.0, 10011, 24019, "2030/12/17 14:59:59", 0, 24, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (10, "2019/01/31 12:00:00", 0.0, 109102, 0.0, "シズル（バレンタイン）", 0.0, 10011, 24020, "2030/12/17 14:59:59", 0, 24, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106401, 0.0, "シェフィ", 0.0, 0, 26001, "2030/12/17 14:59:59", 2104010, 26, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", 2, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105801, 0.0, "ペコリーヌ", 0.0, 0, 26002, "2030/12/17 14:59:59", 0, 26, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106001, 0.0, "キャル", 0.0, 0, 26003, "2030/12/17 14:59:59", 0, 26, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 26004, "2030/12/17 14:59:59", 0, 26, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106401, 0.0, "シェフィ", 0.0, 0, 27001, "2030/12/17 14:59:59", 2104010, 27, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", 2, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105801, 0.0, "ペコリーヌ", 0.0, 0, 27002, "2030/12/17 14:59:59", 0, 27, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106001, 0.0, "キャル", 0.0, 0, 27003, "2030/12/17 14:59:59", 0, 27, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 27004, "2030/12/17 14:59:59", 0, 27, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2019/09/24 15:00:00", -363.0, 190801, 0.0, "カリン", 0.0, 0, 28001, "2030/12/17 14:59:59", 0, 28, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (2, "2019/09/24 15:00:00", -363.0, 190801, 0.0, "カリン", 0.0, 0, 28002, "2030/12/17 14:59:59", 0, 28, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (3, "2019/09/24 15:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 29001, "2030/12/17 14:59:59", 0, 29, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (4, "2019/09/24 15:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 29002, "2030/12/17 14:59:59", 0, 29, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (5, "2019/09/24 15:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 30001, "2030/12/17 14:59:59", 0, 30, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (6, "2019/09/24 15:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 30002, "2030/12/17 14:59:59", 0, 30, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (7, "2019/10/31 12:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 31001, "2030/12/17 14:59:59", 0, 31, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (8, "2019/10/31 12:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 31002, "2030/12/17 14:59:59", 0, 31, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2019/12/20 5:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 32001, "2020/01/04 4:59:59", 0, 32, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (2, "2019/12/20 5:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 32002, "2020/01/04 4:59:59", 0, 32, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (3, "2019/12/20 5:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 33001, "2020/01/04 4:59:59", 0, 33, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (4, "2019/12/20 5:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 33002, "2020/01/04 4:59:59", 0, 33, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (5, "2020/01/04 5:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 34001, "2020/01/10 11:59:59", 0, 34, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (6, "2020/01/04 5:00:00", -409.0, 190801, 0.0, "カリン", 0.0, 0, 34002, "2020/01/10 11:59:59", 0, 34, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -458.0, 105801, 0.0, "ペコリーヌ", 5.3, 0, 38001, "2030/12/17 14:59:59", 0, 38, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", 1, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (2, "2015/12/17 15:00:00", -458.0, 105801, 0.0, "ペコリーヌ", 6.5, 0, 38002, "2030/12/17 14:59:59", 0, 38, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", 1, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (0, "2020/04/01", 9999.0, 105801, 9999.0, "ペコリーヌ", 0.0, 0, 39005, "2020/04/08 23:59:59", 0, 39, "", 3, 3);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (2, "2015/12/17 15:00:00", -430.0, 190801, 0.0, "カリン", 0.0, 0, 40001, "2030/12/17 14:59:59", 0, 40, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106401, 0.0, "シェフィ", 0.0, 0, 41001, "2030/12/17 14:59:59", 2104010, 41, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105801, 0.0, "ペコリーヌ", 0.0, 0, 41002, "2030/12/17 14:59:59", 0, 41, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106001, 0.0, "キャル", 0.0, 0, 41003, "2030/12/17 14:59:59", 0, 41, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 41004, "2030/12/17 14:59:59", 0, 41, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -416.5, 105901, 0.0, "コッコロ", 0.0, 0, 42001, "2030/12/17 14:59:59", 0, 42, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -416.5, 106401, 0.0, "シェフィ", 0.0, 0, 42002, "2030/12/17 14:59:59", 2104010, 42, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -416.5, 105801, 0.0, "ペコリーヌ", 0.0, 0, 42003, "2030/12/17 14:59:59", 0, 42, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -416.5, 106001, 0.0, "キャル", 0.0, 0, 42004, "2030/12/17 14:59:59", 0, 42, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105801, 0.0, "ペコリーヌ", 0.0, 0, 43001, "2030/12/17 14:59:59", 0, 43, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 105901, 0.0, "コッコロ", 0.0, 0, 43002, "2030/12/17 14:59:59", 0, 43, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -363.0, 106001, 0.0, "キャル", 0.0, 0, 43003, "2030/12/17 14:59:59", 0, 43, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -416.5, 123001, 0.0, "アメス", 0.0, 0, 43004, "2030/12/17 14:59:59", 0, 44, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (2, "2015/12/17 15:00:00", -416.5, 123001, 0.0, "アメス", 0.0, 0, 43005, "2030/12/17 14:59:59", 0, 44, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (3, "2015/12/17 15:00:00", -416.5, 123001, 0.0, "アメス", 5.79, 0, 43006, "2030/12/17 14:59:59", 0, 45, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 1, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -371.5, 123001, 0.0, "アメス", 0.0, 0, 46001, "2030/12/17 14:59:59", 0, 46, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 1, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -416.5, 104901, 0.0, "シズル", 0.0, 0, 47001, "2030/12/17 14:59:59", 0, 47, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 2, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (1, "2015/12/17 15:00:00", -416.5, 101101, 0.0, "リノ", 9.32, 0, 47002, "2030/12/17 14:59:59", 0, 47, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", 1, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (0, "2015/12/17 15:00:00", -470.0, 104901, 0.0, "シズル", 0.0, 0, 48001, "2030/12/17 14:59:59", 0, 48, "", 2, 2);
